function hourKey(now=Date.now()){return Math.floor(now/3600000)*3600000}
function dayKey(now){const parts=new Intl.DateTimeFormat('en-US',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const f=t=>parts.find(p=>p.type===t).value;return Math.floor(Date.UTC(+f('year'),+f('month')-1,+f('day'))/86400000)}
function inventory(now=Date.now()){const h=Math.floor(hourKey(now)/3600000);return Array.from({length:8},(_,i)=>({...catalog[((h*5+i*7)%24+24)%24],quantity:3+(i%4)}))}
const tones={practical:['Thank you, Mayor. That goes straight toward the essentials.','Payment received. I appreciate you keeping things square.','Much obliged. I can put that to good use.','That helps cover the bills. Thank you.','A fair payment makes a good working day.'],cheerful:['Oh, thank you! You just made my day!','Look at that! Thank you, Mayor!','You remembered! That means a lot to me.','A little breathing room and a big smile. Thank you!','Wonderful! I’ll put every coin to good use.'],reserved:['Thank you. I appreciate it.','Received, Mayor. Much obliged.','That is thoughtful of you.','Thank you for remembering me.','I am grateful. Truly.'],bold:['Now that’s what I call good leadership!','A solid payday. You can count on me, Mayor.','Well earned and well received. Thank you!','That puts some wind in my sails!','Excellent. Let’s keep Amusa moving.'],scholarly:['A welcome contribution to my carefully balanced accounts.','My ledger and I are both grateful.','Thank you, Mayor. The arithmetic looks considerably brighter.','A most practical encouragement. Much appreciated.','I shall record this with gratitude and unusually tidy handwriting.']};
